import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Connectors (Connect-It)","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/connectors.md","filePath":"self-hosted/connectors.md","lastUpdated":1792323081000}'),s={name:"self-hosted/connectors.md"};function r(i,e,h,c,d,l){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="connectors-connect-it" tabindex="-1">Connectors (Connect-It) <a class="header-anchor" href="#connectors-connect-it" aria-label="Permalink to &quot;Connectors (Connect-It)&quot;">​</a></h1><p>Connectors let bots use tools from third-party services such as GitHub and Notion. They are backed by <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a>, a companion service deployed alongside Memoh. All credentials (OAuth tokens, API keys) live on the Connect-It side; Memoh only keeps a binding table — which bot is bound to which connection, what the tool namespace is called, and whether it is enabled.</p><p>From a user&#39;s point of view, connectors are not installed on their own: they arrive as components of an <a href="./../guides/supermarket.html">App</a>. An App&#39;s manifest declares which connector types it uses and whether each is required; after installing, you authorize them on the bot&#39;s <strong>Apps</strong> tab. The rest of this page is the operator view — how to run Connect-It and how connections work underneath.</p><hr><h2 id="server-requirements" tabindex="-1">Server requirements <a class="header-anchor" href="#server-requirements" aria-label="Permalink to &quot;Server requirements&quot;">​</a></h2><p>The connector feature only appears when the server has a Connect-It endpoint configured:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # e.g. &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # trusted server-to-server token</span></span></code></pre></div><p>Leaving both empty disables the feature. In production, prefer the corresponding environment variables (<code>MEMOH_CONNECT_IT_BASE_URL</code>, <code>MEMOH_CONNECT_IT_API_TOKEN</code>).</p><p>The one-line Server Deploy brings up a co-hosted Connect-It on fresh installs; see <a href="./docker.html#connect-it-connectors">Server Deploy</a>. Without Connect-It configured, App components that depend on a connector show as unavailable.</p><hr><h2 id="authorization-and-management" tabindex="-1">Authorization and management <a class="header-anchor" href="#authorization-and-management" aria-label="Permalink to &quot;Authorization and management&quot;">​</a></h2><p>After installing an App that carries connectors, the bot&#39;s <strong>Apps</strong> tab lists them among the App&#39;s components, marked <strong>Needs authorization</strong>, <strong>Optional</strong>, or <strong>Shared across workspaces</strong>. Click <strong>Authorize</strong> to complete the binding — OAuth runs through a popup (allow popups for the page if the browser blocks it); API-key connectors ask for the credential fields instead.</p><p>Each connection shows a status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Connected</strong></td><td>Healthy; tools are available to the bot</td></tr><tr><td><strong>Waiting for authorization</strong></td><td>The connection exists but OAuth never finished; complete it or disconnect</td></tr><tr><td><strong>Authorization required</strong></td><td>Credentials expired or were revoked; click <strong>Reauthorize</strong></td></tr><tr><td><strong>Authorization failed</strong></td><td>The last authorization attempt failed; <strong>Reauthorize</strong> retries it</td></tr><tr><td><strong>Unavailable</strong></td><td>The configured Connect-It does not provide this connector type</td></tr><tr><td><strong>Disabled</strong></td><td>Turned off; tools are not given to the bot</td></tr></tbody></table><p>You can <strong>enable / disable</strong> a connection without deleting it. <strong>Disconnect</strong> removes the binding from the bot <strong>and</strong> deletes the stored connection (credentials included) on the Connect-It side — Apps that used it will need to be reauthorized.</p><hr><h2 id="how-tools-reach-the-bot" tabindex="-1">How tools reach the bot <a class="header-anchor" href="#how-tools-reach-the-bot" aria-label="Permalink to &quot;How tools reach the bot&quot;">​</a></h2><p>During conversation, Memoh aggregates all of a bot&#39;s enabled, healthy connections into one MCP session and hands it to the agent as a tool source. Connector tools appear alongside workspace and MCP tools.</p><p>Each connection receives a <strong>tool namespace</strong> generated from its connector type at binding time — a GitHub connection is <code>github</code>, a second one becomes <code>github-2</code>. The namespace stays fixed for the lifetime of the binding: adding or removing other connections later never changes the tool names of existing ones.</p><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./../guides/supermarket.html">Supermarket</a> — where Apps (connector components included) are installed from.</li><li><a href="./../guides/mcp.html">MCP</a> — manage MCP connections directly.</li><li><a href="./docker.html#connect-it-connectors">Server Deploy</a> — co-hosting Connect-It, credential management, and OAuth callback URLs.</li></ul>`,22)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
